/* ============================================================
   全局字体
   ============================================================ */
* {
    font-family: 'MapleMono NF CN', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif !important;
    font-synthesis: none;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
    font-feature-settings: "liga", "calt";
}

/* ============================================================
   图标字体保护（防止被全局字体覆盖）
   ============================================================ */
.fa, .fas, .far, .fal, .fab,
[class*="fa-"],
.material-icons, .material-icons-outlined, .material-icons-round, .material-icons-sharp,
.material-symbols-outlined,
.bi, [class*="bi-"],
.octicon,
[class*="iconfont"], [class*="icon-"],
i[class*="icon"], span[class*="icon"] {
    font-family: inherit !important;
}

[style*="Font Awesome"], [style*="font awesome"],
[style*="Material Icons"], [style*="material icons"],
[style*="Bootstrap Icons"], [style*="bootstrap-icons"],
[style*="octicons"] {
    font-family: inherit !important;
}
